    'admin_smtp_setup_host_port_desc'         => 'Identifiziert den Mailserver, der Antworten für deine Domain weiterleitet.',
    'admin_smtp_setup_host_port_where'        => 'Rufe in cPanel E-Mail-Konten → Verwalten → Connect Devices → Mail Client Manual Settings auf und kopiere Hostname, SSL/TLS-Modus und Port; bei Google Workspace, Microsoft 365, Plesk & Co. findest du dieselben Angaben im SMTP/Outgoing-Mail-Bereich.',
    'admin_smtp_setup_host_port_errors'       => 'Falscher Host, Port oder Verschlüsselung führt zu TLS-Handshakes, "Could not connect to SMTP host" oder Zeitüberschreitungen beim Versenden.',
    'admin_smtp_setup_host_port_examples'     => 'Shared-Hosting-Beispiel: dizzyscripts.com (SSL, Port 465). Weitere gängige Werte: smtp.gmail.com (STARTTLS, Port 587), email-smtp.eu-west-1.amazonaws.com (TLS, Port 587).',
    'admin_smtp_setup_host_port_security'     => 'Bevorzuge verschlüsselte Ports, prüfe das Zertifikat und vermeide Klartext-Port 25, um Credential-Diebstahl zu verhindern.',
    'admin_smtp_setup_auth_title'             => 'Authentifizierung & App-Passwörter',
    'admin_smtp_setup_auth_desc'              => 'Zugangsdaten bestätigen, dass dieses System berechtigt ist, E-Mails im Namen des Postfachs zu versenden.',
    'admin_smtp_setup_auth_where'             => 'Nutze in cPanel E-Mail-Konten → Verwalten, um den SMTP-Benutzernamen (vollständige Adresse) abzulesen und bei Bedarf das Passwort zurückzusetzen; gehe analog in Google Workspace, Microsoft 365 oder anderen SMTP-Dashboards vor.',
    'admin_smtp_setup_auth_errors'            => 'Falsche Daten oder eine abweichende From-Adresse gegenüber dem authentifizierten Postfach führen zu 535/534-Fehlern und stoppen jeden Versand.',
    'admin_smtp_setup_auth_examples'          => 'Trage die vollständige Adresse (z. B. creatorpulse@dizzyscripts.com) sowohl als SMTP-Benutzername als auch im From-Email-Feld ein; Anbieter wie Google Workspace oder Outlook 365 verlangen oft app-spezifische Passwörter.',
    'admin_smtp_setup_auth_security'          => 'Bewahre Passwörter sicher auf, rotiere sie regelmäßig, aktiviere wo möglich 2FA und verwende SMTP-Zugangsdaten nicht erneut für interaktive Logins oder Fremddienste.',
    'admin_smtp_setup_spf_dkim_title'         => 'Domain-Authentifizierung (SPF & DKIM)',
    'admin_smtp_setup_spf_dkim_desc'          => 'SPF- und DKIM-DNS-Einträge erlauben empfangenden Servern zu prüfen, dass dieser SMTP-Host für deine Domain autorisiert ist.',
    'admin_smtp_setup_spf_dkim_where'         => 'Veröffentliche SPF/DKIM-Werte bei deinem DNS-Host (Cloudflare, Route53, cPanel) mithilfe der Strings deines Mailanbieters.',
    'admin_smtp_setup_spf_dkim_errors'        => 'Fehlende oder falsche Einträge führen zu "SPF fail" oder "DKIM none" und lassen legitime Mails im Spam landen oder blockieren sie.',
    'admin_smtp_setup_spf_dkim_examples'      => 'Beispiel-SPF: v=spf1 include:_spf.google.com ~all. Beispiel-DKIM: google._domainkey.deinedomain.com mit dem öffentlichen Schlüssel von Google Workspace.',
    'admin_smtp_setup_spf_dkim_security'      => 'Prüfe nach dem Veröffentlichen mit MXToolbox oder Google Postmaster und überwache DMARC-Berichte auf Spoofing.',
    'admin_smtp_setup_test_title'             => 'Zustellung testen & überwachen',
    'admin_smtp_setup_test_desc'              => 'Regelmäßige Testsendungen bestätigen den kompletten Mailflow – Credentials, TLS, Routing – bevor Kunden darauf vertrauen.',
    'admin_smtp_setup_test_where'             => 'Nutze den Button "Test-E-Mail senden" oder CLI-Tools (swaks, openssl s_client), um eine Nachricht an ein eigenes Postfach zu schicken.',
    'admin_smtp_setup_test_errors'            => 'Analysiere SMTP-Codes wie 454 TLS not available oder 550 relay denied, um zu sehen, wo der Versand scheitert.',
    'admin_smtp_setup_test_examples'          => 'Sende Tests an dein Support-Postfach und eine externe Adresse (Gmail/Outlook), um Header und Spam-Placement zu prüfen.',
    'admin_smtp_setup_test_security'          => 'Protokolliere Testergebnisse, beobachte Bounces und Beschwerden und aktiviere DMARC-Reports für schnelle Regressionserkennung.',
    'admin_smtp_setup_alt_title'              => 'Alternative SMTP-Dienste',
    'admin_smtp_setup_alt_desc'               => 'Spezialisierte Anbieter liefern robuste Infrastruktur, Analysen und Reputation-Management, wenn Shared Hosting limitiert.',
    'admin_smtp_setup_alt_where'              => 'Bewerte SendGrid, Mailgun, Amazon SES, Postmark, Brevo u. a.; alle stellen SMTP-Zugangsdaten und Dashboards bereit.',
    'admin_smtp_setup_alt_errors'             => 'Gedrosselte Shared-Hosts riskieren Verzögerungen, Blacklisting oder verlorene Benachrichtigungen bei Lastspitzen.',
    'admin_smtp_setup_alt_examples'           => 'Beispiele: smtp.sendgrid.net (TLS/587, Benutzer "apikey"), smtp.mailgun.org (TLS/587), email-smtp.us-east-1.amazonaws.com (TLS/587).',
